styles:
/* ===== Single job posting (scoped) ===== */
.page-career .career-hero { padding-top: clamp(140px, 18vh, 220px); padding-bottom: clamp(24px, 4vw, 48px); }
.page-career .measure { max-width: 760px; margin-inline: auto; }
.page-career .career-hero__eyebrow { color: var(--red); font-size: clamp(15px, 1.2vw, 18px); margin-bottom: 18px; }
.page-career .career-hero__title {
  font-family: var(--font-display);
  font-size: clamp(40px, 7vw, 82px);
  line-height: 1.06; color: var(--grey-700); letter-spacing: -0.01em;
}
.page-career .career-meta {
  display: flex; flex-wrap: wrap; gap: clamp(14px, 2vw, 28px);
  margin-top: clamp(24px, 3vw, 38px);
  padding-top: clamp(20px, 2.4vw, 30px);
  border-top: 1px solid var(--line);
}
.page-career .career-meta__item { display: flex; flex-direction: column; gap: 4px; }
.page-career .career-meta__label {
  font-size: 12px; letter-spacing: .12em; text-transform: uppercase; color: var(--grey-500);
}
.page-career .career-meta__value {
  font-family: var(--font-display); font-size: clamp(17px, 1.4vw, 21px); color: var(--grey-900);
}

.page-career .job-section { padding-top: clamp(34px, 4vw, 56px); }
.page-career .job-section + .job-section { border-top: 1px solid var(--line); }
.page-career .job-section__title {
  font-family: var(--font-display); font-size: clamp(26px, 3vw, 40px);
  color: var(--grey-900); line-height: 1.1; margin-bottom: clamp(16px, 1.8vw, 24px);
}
.page-career .job-section p { color: var(--grey-700); font-size: clamp(16px, 1.15vw, 18px); line-height: 1.75; }
.page-career .job-section p + p { margin-top: 16px; }
.page-career .job-list { display: flex; flex-direction: column; gap: 14px; margin-top: 4px; }
.page-career .job-list li {
  position: relative; padding-left: 30px;
  color: var(--grey-700); font-size: clamp(16px, 1.15vw, 18px); line-height: 1.6;
}
.page-career .job-list li::before {
  content: ""; position: absolute; left: 4px; top: .62em;
  width: 9px; height: 9px; border-radius: 50%; background: var(--red);
}

.page-career .apply-cta {
  margin-top: clamp(30px, 4vw, 52px);
  display: flex; flex-wrap: wrap; align-items: center; gap: 22px;
}
.page-career .apply-cta .cta__btn { margin-top: 0; }
.page-career .back-roles {
  display: inline-flex; align-items: center; gap: 8px;
  color: var(--grey-700); font-size: 16px; transition: color .25s var(--ease);
}
.page-career .back-roles:hover { color: var(--red); }
.page-career .back-top {
  margin-top: clamp(40px, 5vw, 70px); padding-top: clamp(22px, 2.4vw, 30px);
  border-top: 1px solid var(--line);
}
